/**
 * ATDD RED-PHASE acceptance scaffolds — Story 12.1 (AC1, AC5, AC7, AC8)
 * Provider-policy, weekly-workflow, documentation, and no-live-provider contracts.
 *
 * Every scaffold stays skipped until the implementation task activates it.
 * No test in this file makes an outbound provider request.
 */
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, test } from 'vitest';

const projectRoot = process.cwd();
const repoRoot = join(projectRoot, '..');

function readOptional(path: string): string {
  return existsSync(path) ? readFileSync(path, 'utf8') : '';
}

function collectTextFiles(root: string): string[] {
  if (!existsSync(root)) return [];
  const result: string[] = [];
  for (const entry of readdirSync(root)) {
    const full = join(root, entry);
    if (statSync(full).isDirectory()) {
      result.push(...collectTextFiles(full));
    } else if (/\.(?:ts|tsx|js|mjs|cjs|json|ya?ml)$/i.test(entry)) {
      result.push(full);
    }
  }
  return result;
}

const productionFiles = [
  ...collectTextFiles(join(projectRoot, 'app')),
  ...collectTextFiles(join(projectRoot, 'lib')),
  ...collectTextFiles(join(projectRoot, 'scripts')),
  ...collectTextFiles(join(repoRoot, '.github', 'workflows')),
];
const productionSource = productionFiles
  .map((file) => '\nFILE: ' + file + '\n' + readOptional(file))
  .join('\n');

const setupSource = readOptional(join(projectRoot, 'test', 'setup', 'setup.ts'));
const storySource = readOptional(
  join(
    repoRoot,
    '_bmad-output',
    'implementation-artifacts',
    '12-1-google-places-opening-hours-sync-weekly-scheduled-replace-hand-maintained-hours.md',
  ),
);
const authoringDoc = readOptional(join(projectRoot, 'docs', 'venue-data-load.md'));
const scheduledDoc = readOptional(
  join(projectRoot, 'docs', 'github-actions-scheduled-jobs.md'),
);
const environmentDoc = readOptional(
  join(projectRoot, 'docs', 'environment-variables.md'),
);
const envExample = readOptional(join(projectRoot, '.env.example'));
const hoursWorkflow = readOptional(
  join(repoRoot, '.github', 'workflows', 'hours-review-audit.yml'),
);
const legacyWorkflow = readOptional(
  join(repoRoot, '.github', 'workflows', 'scheduled-cron-jobs.yml'),
);

describe('[12.1 AC1/AC8] Google-hours path stays prohibited', () => {
  test.skip('[P1] production and scheduled code has no Google hours/content/credential path', () => {
    expect(productionSource).not.toMatch(/regularOpeningHours/i);
    expect(productionSource).not.toMatch(/X-Goog-FieldMask[^\n]*opening/i);
    expect(productionSource).not.toMatch(/places\.googleapis\.com/i);
    expect(productionSource).not.toMatch(/places_api_url/i);
    expect(productionSource).not.toMatch(
      /\b(?:GOOGLE|PLACES)[A-Z0-9_]*(?:API_KEY|CREDENTIAL|SECRET)\b/,
    );
  });

  test.skip('[P1] public code has no hours-provider route or request-path integration', () => {
    expect(productionFiles.some((file) => /app[\\/]api[\\/]cron/i.test(file))).toBe(false);
    expect(productionSource).not.toMatch(/fetch\([^\n]*(?:google|places|nominatim)/i);
  });

  test.skip('[P1] shared test setup hard-blocks Google/provider hosts with a fix hint', () => {
    expect(setupSource).toMatch(/places\.googleapis\.com/i);
    expect(setupSource).toMatch(/no live|forbidden|fetch guard/i);
    expect(setupSource).toMatch(/mock|inject/i);
  });

  test.skip('[P1] story brief preserves the explicit supersession and controlling decisions', () => {
    expect(storySource).toContain('## Superseded Epic Text');
    expect(storySource).toContain('sprint-change-proposal-2026-07-12.md');
    expect(storySource).toContain('technical-google-places-api-policy-epic-12-research-2026-07-12.md');
    expect(storySource).toContain('E12-AD-01');
    expect(storySource).toContain('E12-AD-13');
  });
});

describe('[12.1 AC5/AC7] direct weekly audit workflow and operations docs', () => {
  test.skip('[P1] dedicated workflow is weekly, manually dispatchable, non-overlapping, and direct-script only', () => {
    expect(hoursWorkflow).toMatch(/schedule:/);
    expect(hoursWorkflow).toMatch(/cron:/);
    expect(hoursWorkflow).toMatch(/workflow_dispatch:/);
    expect(hoursWorkflow).toMatch(/concurrency:/);
    expect(hoursWorkflow).toMatch(/environment:\s*production/);
    expect(hoursWorkflow).toMatch(/audit-opening-hours\.mjs/);
    expect(hoursWorkflow).toMatch(/SUN_HOURS_AUDIT_ENABLED/);
    expect(hoursWorkflow).not.toMatch(/\/api\/cron\//);
    expect(hoursWorkflow).not.toMatch(/CRON_SECRET/);
    expect(hoursWorkflow).not.toMatch(/GOOGLE|PLACES_API_KEY/i);
  });

  test.skip('[P1] workflow is main-branch/protected-environment scoped with bounded execution and summary output', () => {
    expect(hoursWorkflow).toMatch(/refs\/heads\/main|branches:\s*\[?main/i);
    expect(hoursWorkflow).toMatch(/timeout-minutes:/);
    expect(hoursWorkflow).toMatch(/GITHUB_STEP_SUMMARY/);
    expect(hoursWorkflow).toMatch(/run[_ -]?id/i);
  });

  test.skip('[P1] legacy scheduled workflow no longer offers or invokes OSM ingestion', () => {
    expect(legacyWorkflow).not.toMatch(/osm-ingestion/i);
    expect(legacyWorkflow).not.toMatch(/\/api\/cron\/osm/i);
  });

  test.skip('[P1] authoring docs remove provider URL examples and explain provider-neutral evidence', () => {
    expect(authoringDoc).not.toMatch(/places_api_url/i);
    expect(authoringDoc).not.toMatch(/places\.googleapis\.com\/v1\/places/i);
    expect(authoringDoc).toMatch(/Place ID[- ]only|Place-ID-only/i);
    expect(authoringDoc).toMatch(/venue_confirmed|venue_website|licensed_provider|manual/);
    expect(authoringDoc).toMatch(/unknown|unknown hours/i);
    expect(authoringDoc).toMatch(/split|24\/7|seasonal|holiday/i);
  });

  test.skip('[P1] scheduled-job and environment docs describe the direct audit and emergency stop', () => {
    const operationsText = scheduledDoc + '\n' + environmentDoc + '\n' + envExample;
    expect(operationsText).toMatch(/audit-opening-hours\.mjs/);
    expect(operationsText).toMatch(/workflow_dispatch/);
    expect(operationsText).toMatch(/SUN_HOURS_AUDIT_ENABLED/);
    expect(operationsText).toMatch(/180 days|180-day/i);
    expect(operationsText).not.toMatch(/GOOGLE_MAPS|PLACES_API_KEY/i);
  });
});

/**
 * ATDD RED-PHASE acceptance scaffolds — Story 12.1 (AC2, AC8)
 * Repository-authoritative migration and service-only schema contracts.
 */
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, test } from 'vitest';

const repoRoot = join(process.cwd(), '..');
const migrationsDir = join(repoRoot, 'supabase', 'migrations');

function migrationFiles(): string[] {
  if (!existsSync(migrationsDir)) return [];
  return readdirSync(migrationsDir)
    .filter((file) => file.endsWith('.sql'))
    .sort();
}

function readMigration(namePart: string): string {
  const file = migrationFiles().find((candidate) => candidate.includes(namePart));
  return file ? readFileSync(join(migrationsDir, file), 'utf8') : '';
}

const reconciliation = readMigration('reconcile_venue_place_identity');
const governance = readMigration('provider_neutral_hours_governance');
const allSql = reconciliation + '\n' + governance;

describe('[12.1 AC2] canonical migration chain', () => {
  test.skip('[P0] reconciliation precedes the forward provider-neutral migration', () => {
    const files = migrationFiles();
    const reconcileIndex = files.findIndex((file) =>
      file.includes('reconcile_venue_place_identity'),
    );
    const governanceIndex = files.findIndex((file) =>
      file.includes('provider_neutral_hours_governance'),
    );
    expect(reconcileIndex).toBeGreaterThanOrEqual(0);
    expect(governanceIndex).toBeGreaterThan(reconcileIndex);
  });

  test.skip('[P0] migration is idempotent and keeps nullable indexed non-unique place_id only', () => {
    expect(allSql).toMatch(/IF\s+(?:NOT\s+)?EXISTS/i);
    expect(allSql).toMatch(/\bplace_id\b/i);
    expect(governance).toMatch(/DROP\s+COLUMN\s+(?:IF\s+EXISTS\s+)?places_api_url/i);
    expect(governance).toMatch(/CREATE\s+INDEX[\s\S]*place_id/i);
    expect(governance).not.toMatch(/UNIQUE[\s\S]{0,80}place_id/i);
  });

  test.skip('[P0] venues gains checked provider-neutral provenance and review fields', () => {
    for (const field of [
      'hours_source_type',
      'hours_source_reference',
      'hours_review_status',
      'hours_reviewed_at',
      'hours_next_review_at',
      'hours_notes',
    ]) {
      expect(governance).toMatch(new RegExp('\\b' + field + '\\b', 'i'));
    }
    expect(governance).toMatch(/venue_confirmed/i);
    expect(governance).toMatch(/venue_website/i);
    expect(governance).toMatch(/licensed_provider/i);
    expect(governance).toMatch(/manual/i);
    expect(governance).toMatch(/verified/i);
    expect(governance).toMatch(/manual_review/i);
    expect(governance).toMatch(/unknown/i);
  });

  test.skip('[P0] service-only run/outcome tables use checked statuses and bounded fields', () => {
    expect(governance).toMatch(/CREATE\s+TABLE[\s\S]*hours_review_runs/i);
    expect(governance).toMatch(/CREATE\s+TABLE[\s\S]*hours_review_outcomes/i);
    for (const outcome of ['due', 'unknown', 'conflict', 'split', 'failed', 'stale']) {
      expect(governance).toMatch(new RegExp('\\b' + outcome + '\\b', 'i'));
    }
    expect(governance).toMatch(/FOREIGN\s+KEY|REFERENCES/i);
    expect(governance).toMatch(/PRIMARY\s+KEY[\s\S]*(?:run_id|venue_id)/i);
  });

  test.skip('[P0] both service tables enable RLS and deny public roles', () => {
    expect(governance).toMatch(
      /ALTER\s+TABLE[\s\S]*hours_review_runs[\s\S]*ENABLE\s+ROW\s+LEVEL\s+SECURITY/i,
    );
    expect(governance).toMatch(
      /ALTER\s+TABLE[\s\S]*hours_review_outcomes[\s\S]*ENABLE\s+ROW\s+LEVEL\s+SECURITY/i,
    );
    expect(governance).toMatch(/REVOKE[\s\S]*FROM\s+(?:PUBLIC|anon)/i);
    expect(governance).toMatch(/REVOKE[\s\S]*FROM\s+authenticated/i);
    expect(governance).not.toMatch(/CREATE\s+POLICY[\s\S]*TO\s+(?:anon|authenticated)/i);
  });

  test.skip('[P0] schema provides atomic non-overlap and deterministic 180-day cleanup seams', () => {
    expect(governance).toMatch(/advisory|non.?overlap|active_run|lease/i);
    expect(governance).toMatch(/180\s*(?:days?|day)/i);
    expect(governance).toMatch(/DELETE\s+FROM[\s\S]*hours_review_(?:runs|outcomes)/i);
  });
});

/**
 * ATDD RED-PHASE acceptance scaffolds — Story 12.1 (AC3, AC4, AC8)
 * Provider-neutral classification, update planning, and remediation contracts.
 */
import { pathToFileURL } from 'node:url';
import { join } from 'node:path';
import { describe, expect, test } from 'vitest';

type GovernanceModule = {
  classifyHoursEvidence(input: Record<string, unknown>): {
    kind: 'accepted' | 'manual_review' | 'failed';
    schedule?: Record<string, { open: string; close: string } | null> | null;
    provenance?: Record<string, unknown>;
    reason?: string;
    errorClass?: string;
  };
  planCanonicalHoursUpdate(input: Record<string, unknown>): {
    shouldWrite: boolean;
    schedule?: Record<string, { open: string; close: string } | null> | null;
    preservesPriorSchedule?: boolean;
    idempotent?: boolean;
  };
  remediateOpeningHoursRows(input: Record<string, unknown>): Promise<{
    updates: Array<Record<string, unknown>>;
    outcomes: Array<Record<string, unknown>>;
  }>;
};

async function loadGovernance(): Promise<GovernanceModule> {
  const moduleUrl = pathToFileURL(
    join(process.cwd(), 'lib', 'services', 'opening-hours-governance.ts'),
  ).href;
  return (await import(/* @vite-ignore */ moduleUrl)) as GovernanceModule;
}

const eligibleEvidence = {
  sourceType: 'venue_website',
  sourceReference: 'https://venue.example/oppettider',
  reviewedAt: '2026-07-13T10:00:00.000Z',
  nextReviewAt: '2026-10-13T10:00:00.000Z',
};

describe('[12.1 AC4] provider-neutral adapter outcome union', () => {
  test.skip('[P1] accepts one interval, explicit closed days, and past-midnight without changing shape', async () => {
    const { classifyHoursEvidence } = await loadGovernance();
    const schedule = {
      '1': { open: '11:00', close: '22:00' },
      '2': null,
      '5': { open: '18:00', close: '02:00' },
    };
    expect(classifyHoursEvidence({ ...eligibleEvidence, schedule })).toMatchObject({
      kind: 'accepted',
      schedule,
      provenance: expect.objectContaining({ sourceType: 'venue_website' }),
    });
  });

  test.skip('[P1] preserves whole-field unknown as null rather than seven closed weekdays', async () => {
    const { classifyHoursEvidence } = await loadGovernance();
    const result = classifyHoursEvidence({ ...eligibleEvidence, schedule: null });
    expect(result).toMatchObject({ kind: 'accepted', schedule: null });
    expect(result.schedule).not.toEqual({
      '1': null,
      '2': null,
      '3': null,
      '4': null,
      '5': null,
      '6': null,
      '7': null,
    });
  });

  test.skip.each([
    ['split', { '1': [{ open: '11:00', close: '14:00' }, { open: '17:00', close: '23:00' }] }],
    ['unsupported_24_7', { mode: '24/7' }],
    ['seasonal', { seasonal: true, schedule: { '1': { open: '11:00', close: '22:00' } } }],
    ['holiday_specific', { holidaySpecific: true, schedule: { '1': { open: '11:00', close: '22:00' } } }],
  ])('[P1] routes %s evidence wholesale to manual review', async (reason, schedule) => {
    const { classifyHoursEvidence } = await loadGovernance();
    const result = classifyHoursEvidence({ ...eligibleEvidence, schedule });
    expect(result.kind).toBe('manual_review');
    expect(result.reason).toMatch(new RegExp(String(reason).replace('_', '.?'), 'i'));
    expect(result.schedule).toBeUndefined();
  });

  test.skip('[P1] malformed evidence fails with a bounded error class', async () => {
    const { classifyHoursEvidence } = await loadGovernance();
    expect(
      classifyHoursEvidence({ ...eligibleEvidence, schedule: { '1': { open: '11', close: 'tomorrow' } } }),
    ).toMatchObject({ kind: 'failed', errorClass: expect.any(String) });
  });
});

describe('[12.1 AC3/AC4] canonical update and remediation behavior', () => {
  test.skip('[P1] only accepted outcomes write atomically and an identical rerun is idempotent', async () => {
    const { planCanonicalHoursUpdate } = await loadGovernance();
    const schedule = { '1': { open: '11:00', close: '22:00' } };
    const accepted = { kind: 'accepted', schedule, provenance: eligibleEvidence };
    expect(planCanonicalHoursUpdate({ current: null, outcome: accepted })).toMatchObject({
      shouldWrite: true,
      schedule,
    });
    expect(
      planCanonicalHoursUpdate({
        current: { schedule, provenance: eligibleEvidence },
        outcome: accepted,
      }),
    ).toMatchObject({ shouldWrite: false, idempotent: true });
  });

  test.skip.each(['manual_review', 'failed'])(
    '[P1] %s never overwrites the prior independently verified schedule',
    async (kind) => {
      const { planCanonicalHoursUpdate } = await loadGovernance();
      const prior = { '1': { open: '11:00', close: '22:00' } };
      expect(
        planCanonicalHoursUpdate({
          current: { schedule: prior, provenance: eligibleEvidence },
          outcome: kind === 'failed'
            ? { kind, errorClass: 'provider_failure' }
            : { kind, reason: 'split' },
        }),
      ).toMatchObject({
        shouldWrite: false,
        preservesPriorSchedule: true,
      });
    },
  );

  test.skip('[P1] remediation classifies every row and deletes unproven/restricted schedules to whole-field unknown', async () => {
    const { remediateOpeningHoursRows } = await loadGovernance();
    const result = await remediateOpeningHoursRows({
      rows: [
        { id: '1', slug: 'verified', openingHours: { '1': { open: '11:00', close: '22:00' } }, evidence: eligibleEvidence },
        { id: '2', slug: 'unproven', openingHours: { '1': { open: '11:00', close: '22:00' } }, evidence: null },
        { id: '3', slug: 'restricted', openingHours: { '1': { open: '11:00', close: '22:00' } }, evidence: { sourceType: 'google' } },
      ],
    });
    expect(result.outcomes).toHaveLength(3);
    expect(result.updates).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ id: '2', openingHours: null }),
        expect.objectContaining({ id: '3', openingHours: null }),
      ]),
    );
    expect(JSON.stringify(result)).not.toMatch(/seven closed|relabelled.*manual/i);
  });

  test.skip('[P1] duplicate Place IDs remain distinct venue outcomes', async () => {
    const { remediateOpeningHoursRows } = await loadGovernance();
    const result = await remediateOpeningHoursRows({
      rows: [
        { id: '10', slug: 'seating-a', placeId: 'shared-place', openingHours: null, evidence: eligibleEvidence },
        { id: '11', slug: 'seating-b', placeId: 'shared-place', openingHours: null, evidence: eligibleEvidence },
      ],
    });
    expect(result.outcomes.map((outcome) => outcome.venueId)).toEqual(['10', '11']);
  });
});

/**
 * ATDD RED-PHASE acceptance scaffolds — Story 12.1 (AC5, AC8)
 * Deterministic weekly hours-review audit service contract.
 */
import { pathToFileURL } from 'node:url';
import { join } from 'node:path';
import { describe, expect, test, vi } from 'vitest';

type AuditModule = {
  classifyHoursAuditVenue(input: Record<string, unknown>): {
    outcome: string;
    reason: string;
  };
  runOpeningHoursAudit(input: Record<string, unknown>): Promise<{
    status: string;
    runId?: string;
    counts?: Record<string, number>;
  }>;
};

async function loadAudit(): Promise<AuditModule> {
  const moduleUrl = pathToFileURL(
    join(process.cwd(), 'lib', 'services', 'opening-hours-audit.ts'),
  ).href;
  return (await import(/* @vite-ignore */ moduleUrl)) as AuditModule;
}

const NOW = new Date('2026-07-13T10:00:00.000Z');

describe('[12.1 AC5] weekly audit classification', () => {
  test.skip.each([
    ['missing_provenance', { openingHours: { '1': { open: '11:00', close: '22:00' } }, provenance: null }],
    ['due', { openingHours: { '1': { open: '11:00', close: '22:00' } }, provenance: { nextReviewAt: '2026-07-12T00:00:00.000Z' } }],
    ['unknown', { openingHours: null, provenance: { reviewStatus: 'unknown' } }],
    ['conflicting', { openingHours: { '1': { open: '11:00', close: '22:00' } }, provenance: { reviewStatus: 'manual_review', conflict: true } }],
    ['split', { openingHours: { '1': { open: '11:00', close: '22:00' } }, provenance: { reviewStatus: 'manual_review', reason: 'split' } }],
    ['failed', { openingHours: { '1': { open: '11:00', close: '22:00' } }, provenance: { reviewStatus: 'due', lastErrorClass: 'read_failed' } }],
    ['stale', { openingHours: { '1': { open: '11:00', close: '22:00' } }, provenance: { reviewStatus: 'verified', reviewedAt: '2025-01-01T00:00:00.000Z' } }],
  ])('[P1] classifies %s without changing canonical hours', async (expected, venue) => {
    const { classifyHoursAuditVenue } = await loadAudit();
    expect(classifyHoursAuditVenue({ venue, now: NOW })).toMatchObject({
      outcome: expected,
      reason: expect.any(String),
    });
  });
});

describe('[12.1 AC5] audit runner isolation, overlap, retention, and idempotency', () => {
  test.skip('[P1] emergency stop is fail-closed and claims no run', async () => {
    const { runOpeningHoursAudit } = await loadAudit();
    const claimRun = vi.fn();
    await expect(
      runOpeningHoursAudit({ enabled: false, now: NOW, repositories: { claimRun } }),
    ).resolves.toMatchObject({ status: 'disabled' });
    expect(claimRun).not.toHaveBeenCalled();
  });

  test.skip('[P1] a non-overlap claim prevents a second active run', async () => {
    const { runOpeningHoursAudit } = await loadAudit();
    const recordOutcome = vi.fn();
    const result = await runOpeningHoursAudit({
      enabled: true,
      now: NOW,
      repositories: {
        claimRun: vi.fn().mockResolvedValue({ claimed: false, activeRunId: 'run-active' }),
        listVenues: vi.fn(),
        recordOutcome,
      },
    });
    expect(result).toMatchObject({ status: 'already_running' });
    expect(recordOutcome).not.toHaveBeenCalled();
  });

  test.skip('[P1] one venue failure is isolated and canonical hours are never written', async () => {
    const { runOpeningHoursAudit } = await loadAudit();
    const writeCanonicalHours = vi.fn();
    const recordOutcome = vi.fn().mockResolvedValue(undefined);
    const result = await runOpeningHoursAudit({
      enabled: true,
      now: NOW,
      repositories: {
        claimRun: vi.fn().mockResolvedValue({ claimed: true, runId: 'run-1' }),
        listVenues: vi.fn().mockResolvedValue([
          { id: '1', slug: 'ok', openingHours: null, provenance: { reviewStatus: 'unknown' } },
          { id: '2', slug: 'broken', openingHours: null, provenance: { throwForTest: true } },
          { id: '3', slug: 'due', openingHours: { '1': { open: '11:00', close: '22:00' } }, provenance: { nextReviewAt: '2026-07-12T00:00:00.000Z' } },
        ]),
        recordOutcome,
        finishRun: vi.fn().mockResolvedValue(undefined),
        pruneBefore: vi.fn().mockResolvedValue(undefined),
        writeCanonicalHours,
      },
    });
    expect(recordOutcome).toHaveBeenCalledTimes(3);
    expect(result.counts).toMatchObject({ unknown: 1, failed: 1, due: 1 });
    expect(writeCanonicalHours).not.toHaveBeenCalled();
  });

  test.skip('[P1] repeated input produces stable counts and a 180-day retention cutoff', async () => {
    const { runOpeningHoursAudit } = await loadAudit();
    const pruneBefore = vi.fn().mockResolvedValue(undefined);
    const base = {
      enabled: true,
      now: NOW,
      venues: [
        { id: '1', openingHours: null, provenance: { reviewStatus: 'unknown' } },
      ],
      repositories: {
        claimRun: vi.fn()
          .mockResolvedValueOnce({ claimed: true, runId: 'run-1' })
          .mockResolvedValueOnce({ claimed: true, runId: 'run-2' }),
        listVenues: vi.fn().mockResolvedValue([
          { id: '1', openingHours: null, provenance: { reviewStatus: 'unknown' } },
        ]),
        recordOutcome: vi.fn().mockResolvedValue(undefined),
        finishRun: vi.fn().mockResolvedValue(undefined),
        pruneBefore,
      },
    };
    const first = await runOpeningHoursAudit(base);
    const second = await runOpeningHoursAudit(base);
    expect(first.counts).toEqual(second.counts);
    expect(pruneBefore).toHaveBeenCalledWith(
      new Date('2026-01-14T10:00:00.000Z'),
    );
  });
});

/**
 * ATDD RED-PHASE acceptance scaffolds — Story 12.1 (AC6, AC8)
 * Public detail DTO preserves whole-field unknown and leaks no service metadata.
 */
import { NextRequest } from 'next/server';
import { describe, expect, test } from 'vitest';
import { GET } from '@/app/api/venues/[slug]/route';

function request(slug: string): NextRequest {
  return new NextRequest('http://localhost/api/venues/' + slug);
}

async function detail(slug: string): Promise<Record<string, unknown>> {
  const response = await GET(request(slug), {
    params: Promise.resolve({ slug }),
  });
  expect(response.status).toBe(200);
  return (await response.json()) as Record<string, unknown>;
}

describe('[12.1 AC6] honest whole-field unknown at the detail route', () => {
  test.skip('[P0] a real hours-less fixture omits openingHours instead of serializing an empty object', async () => {
    const body = await detail('brygghuset-lerum');
    const venue = body.venue as Record<string, unknown>;
    expect('openingHours' in venue).toBe(false);
  });

  test.skip('[P0] a known-hours fixture keeps the canonical weekday shape unchanged', async () => {
    const body = await detail('test-venue-sunny');
    const venue = body.venue as Record<string, unknown>;
    expect(venue.openingHours).toMatchObject({
